import marimo

__generated_with = "0.25.1"
app = marimo.App()


@app.cell
def _(sp):
    x, L, n, hbar = sp.symbols("x L n hbar", positive=True)
    psi_n = sp.sqrt(2 / L) * sp.sin(n * sp.pi * x / L)
    psi_n
    return L, hbar, psi_n, x


@app.cell
def _(hbar, psi_n, sp, x):
    p2_psi = -hbar**2 * sp.diff(psi_n, x, 2)
    p2_psi
    return (p2_psi,)


@app.cell
def _(L, p2_psi, psi_n, sp, x):
    p2_avg = sp.simplify(sp.integrate(psi_n * p2_psi, (x, 0, L)))
    p2_avg
    return


if __name__ == "__main__":
    app.run()
